"""Phase 2 explicit adverse fixtures plus inherited clock/crew/save regression coverage."""
import argparse,json,unittest
from pathlib import Path
from test_knowledge_integration import KnowledgeIntegration
from test_continuity import RecordedResult
class LivingWorldIntegration(KnowledgeIntegration):
    def test_sealed_chamber_cannot_attack_actual_field_crew(self):
        p=self.page();self.field(p);self.advance(p,5);s=self.snap(p);o=s['unifiedWorld']['organisms']['XENO-INITIAL'];self.assertEqual(o['location'],'asteroid:23');self.assertEqual(o['behavior']['state'],'contained');self.assertFalse(any(e['data'].get('organismId')=='XENO-INITIAL' and e['kind']=='encounter' for e in s['chronicle']['records']))
    def test_local_creature_attack_has_private_source_and_causal_injury(self):
        p=self.page();self.field(p);self.change(p,"""s.tick=4;s.clock.elapsed=4;const q=s.crew[0];q.fieldPosition=23;const o=s.unifiedWorld.organisms['XENO-INITIAL'];o.sealed=false;o.dormant=false;s.unifiedWorld.military.doors[23]='open';s.entropy.seed=9; /* fixed seed whose first local attack draw is below .35 */""");self.advance(p,1);s=self.snap(p);hits=[e for e in s['chronicle']['records'] if e['kind']=='encounter' and e['data'].get('organismId')=='XENO-INITIAL'];self.assertEqual(len(hits),1);self.assertTrue(hits[0]['data']['privateKnowledge']);self.assertTrue(any(e['data'].get('encounterSourceId')==hits[0]['id'] for e in s['chronicle']['records']));self.assertFalse(any(f['id'] in s['knowledge']['actors']['SOL']['entries'] for f in s['knowledge']['facts'].values() if f['data'].get('organismId')=='XENO-INITIAL'));self.assertLess(s['crew'][0]['vitals']['health'],100)
    def test_reduced_motion_and_visual_refresh_do_not_advance_or_mutate_world(self):
        p=self.page();self.operations(p);before=self.snap(p);p.locator('#icarus-menu button[data-page="settings"]').click();p.locator('#reduced-motion').click();self.assertEqual(p.locator('#reduced-motion').get_attribute('aria-pressed'),'true');self.assertTrue(p.evaluate('document.documentElement.classList.contains("reduce-motion")'));self.assertEqual(self.snap(p),before);p.evaluate('__icarusSoak.save()');p.reload();after=self.snap(p);self.assertTrue(p.evaluate('document.documentElement.classList.contains("reduce-motion")'));self.assertEqual(after,before)
    def test_actual_body_and_waiting_pose_on_tablet_and_readonly_docked_render(self):
        p=self.page();self.configure(p,"""s.remoteCore.autonomyEnabled=false;s.remoteCore.derelict.docking='docked';const q=s.crew[0];q.room='C05';q.route=[];q.nav=null;q.task='Waiting for tools';q.interaction='waiting for tools';q.body={build:'large',species:'human',locomotion:'wheelchair'};""");self.operations(p);before=self.snap(p);actor=p.locator('#campeople .cam-person').first;self.assertEqual(actor.get_attribute('data-locomotion'),'wheelchair');self.assertEqual(actor.get_attribute('data-pose'),'idle');self.assertEqual(actor.locator('.mobility-aid').count(),1);self.assertNotIn('cameraAtmosphere(',p.locator('#camera-scene').inner_text());p.set_viewport_size({'width':800,'height':1280});p.screenshot(path='/workspace/work/phase2_reports/2c_tablet.png',full_page=True);p.locator('#icarus-menu button[data-page="settings"]').click();self.operations(p);self.assertEqual(self.snap(p),before)
    def test_host_emergence_keeps_physical_location_after_host_health_reaches_zero(self):
        p=self.page();self.field(p);self.change(p,"""s.tick=239;s.clock.elapsed=239;s.minute=719;const q=s.crew[0],buddy=s.crew[1];buddy.expeditionAway='asteroid';buddy.expeditionId='KNOWLEDGE-FIXTURE';s.remoteCore.missions.asteroid.members.push(buddy.name);s.unifiedWorld.organisms['EGG-1'].stage='spent egg';s.unifiedWorld.organisms['EGG-1'].dormant=false;s.unifiedWorld.infections[q.name]={host:q.name,egg:'EGG-1',started:0,stage:'incubating',variant:{hostSpecies:'human',limbs:2,build:'medium',size:1,locomotion:'bipedal'}};""");self.advance(p,1);s=self.snap(p);o=s['unifiedWorld']['organisms']['XENO-HOST-1'];self.assertEqual(o['location'],'asteroid:23');self.assertEqual(o['stage'],'juvenile');self.assertEqual(len(s['crew']),19);self.assertEqual(s['living']['deceased'][0]['fieldPosition'],23);self.assertEqual(s['knowledgeAudit'],[]);self.assertEqual(s['creatureAudit'],[]);p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),s)
    def test_exact_lunar_dates_and_explicit_personal_configuration_in_browser(self):
        p=self.page();self.deck(p,'settings','advanced');p.locator('summary').filter(has_text='INDIVIDUAL OBSERVANCES').click();p.locator('#personal-shipwide').uncheck();p.locator('#personal-dates').fill('[{"date":"2026-12-04","until":"2026-12-12","name":"Explicit personal observance","enabled":true}]');p.locator('#personal-save').click();self.assertIn('saved',p.locator('#personal-status').inner_text());s=self.snap(p);self.assertEqual(s['unifiedWorld']['preferences']['Frank Morrow']['personal'][0]['until'],'2026-12-12');view=p.evaluate('ICARUSCalendar.atmosphere(Date.parse("2026-08-27T20:00Z"),"Pacific/Honolulu")');self.assertTrue(view['fullMoon']);self.assertTrue(view['lunarSupported']);self.assertEqual(self.snap(p),s)
    def test_reading_ship_records_requires_actual_terminal_and_is_persistent(self):
        p=self.page();self.configure(p,"""const q=s.crew[0];q.room='B06';q.route=[];q.nav=null;""");self.deck(p,'research','evidence');p.locator('summary').filter(has_text='IN-GAME ARCHIVES').click();p.locator('#knowledge-actor').select_option('Frank Morrow');self.assertNotIn('Existing chart',p.locator('#actor-knowledge').inner_text());p.locator('#knowledge-read').click();self.assertIn('Learned',p.locator('#knowledge-status').inner_text());self.assertIn('recorded-evidence',p.locator('#actor-knowledge').inner_text());s=self.snap(p);self.assertGreater(len(s['knowledge']['actors']['Frank Morrow']['entries']),0);p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),s)
    def test_old_room_label_in_corridor_cannot_read_terminal_records(self):
        p=self.page();self.configure(p,"""const q=s.crew[0];q.room='B06';q.route=[];q.nav={at:'H:B:1',steps:[],index:0,progress:0};""");self.deck(p,'research','evidence');p.locator('summary').filter(has_text='IN-GAME ARCHIVES').click();p.locator('#knowledge-actor').select_option('Frank Morrow');p.locator('#knowledge-read').click();self.assertIn('not at a working terminal',p.locator('#knowledge-status').inner_text());self.assertEqual(len(self.snap(p)['knowledge']['actors']['Frank Morrow']['entries']),0)
    def test_pending_personal_report_and_active_field_team_survive_real_monday(self):
        p=self.page();self.field(p);r=self.observe(p);p.evaluate('__icarusSoak.realStart(Date.parse("2026-06-07T23:59Z"),"UTC")');p.evaluate('__icarusSoak.realAdvance(Date.parse("2026-06-08T00:01Z"))');s=self.snap(p);self.assertEqual(s['episode'],2);self.assertEqual(s['missions']['asteroid']['id'],'KNOWLEDGE-FIXTURE');f=next(f for f in s['knowledge']['facts'].values() if f['sourceId']==r['id']);self.assertNotIn(f['id'],s['knowledge']['actors']['SOL']['entries']);self.assertTrue(any(m['factId']==f['id'] and m['status']=='pending' for m in s['knowledge']['messages']));self.assertEqual(s['knowledgeAudit'],[]);p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),s)
    def test_grief_requires_actual_death_knowledge_and_does_not_repeat_after_records_or_reload(self):
        p=self.page();self.field(p);self.change(p,"""s.crew[0].vitals.health=0;const buddy=s.crew[1];buddy.expeditionAway='asteroid';buddy.expeditionId='KNOWLEDGE-FIXTURE';s.remoteCore.missions.asteroid.members.push(buddy.name);const reader=s.crew[2];reader.room='B06';reader.nav=null;reader.route=[];reader.target='B06';reader.task='Reviewing records';reader.goal=reader.task;reader.taskMinutes=999;reader.interaction='working';""");self.advance(p,1);s=self.snap(p);buddy=next(q for q in s['crew'] if q['name']=='Mara Chen');reader=next(q for q in s['crew'] if q['name']=='Dr. Voss');self.assertIn('Frank Morrow',buddy.get('bereavements',{}));self.assertNotIn('Frank Morrow',reader.get('bereavements',{}));f=next(f for f in s['knowledge']['facts'].values() if f['kind']=='death' and f['data'].get('deceased')=='Frank Morrow');self.assertNotIn(f['id'],s['knowledge']['actors']['SOL']['entries']);self.advance(p,60);s=self.snap(p);self.assertIn(f['id'],s['knowledge']['actors']['SOL']['entries']);p.evaluate('(id)=>__icarusSoak.knowledgeAction("read",{actor:"Dr. Voss",id})',f['id']);s=self.snap(p);reader=next(q for q in s['crew'] if q['name']=='Dr. Voss');self.assertIn('Frank Morrow',reader.get('bereavements',{}));before=reader['bereavements'];p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(next(q for q in self.snap(p)['crew'] if q['name']=='Dr. Voss')['bereavements'],before);self.assertFalse(p.evaluate('(id)=>__icarusSoak.knowledgeAction("read",{actor:"Dr. Voss",id})',f['id']))
    def test_adjacent_barrier_observation_is_local_then_delivered_by_actual_relay(self):
        p=self.page();self.field(p);self.change(p,"""s.asteroidExploration.rooms.forEach(r=>{r.visited=true;r.object=null;});s.asteroidExploration.rooms[14].visited=false;s.asteroidExploration.position=13;s.asteroidExploration.step=13;""");self.advance(p,1);s=self.snap(p);f=next(f for f in s['knowledge']['facts'].values() if f['data'].get('map',{}).get('location')=='asteroid' and f['data']['map'].get('cell')==9 and f['data']['map'].get('blocked'));self.assertEqual(f['data']['fromCell'],14);self.assertIn(f['id'],s['knowledge']['actors']['Frank Morrow']['entries']);self.assertNotIn(f['id'],s['knowledge']['actors']['SOL']['entries']);self.change(p,"s.asteroidExploration.fieldRelays=[1,2].map(zone=>({zone,room:zone*5,battery:100,integrity:100}));");self.advance(p,1);self.assertIn(f['id'],self.snap(p)['knowledge']['actors']['SOL']['entries'])
    def test_completed_delivered_surveys_allow_autonomous_navigation_without_a_mission_quota(self):
        c=self.browser.new_context();self.contexts.append(c);c.add_init_script(self.codec+';window.__icarusSeed=1001;');p=c.new_page();p.on('pageerror',lambda e:self.errors.append(str(e)));p.goto(self.url);p.wait_for_function('!!window.__icarusSoak');start=p.evaluate('()=>{const t=Date.parse("2026-10-28T00:00Z");__icarusSoak.realStart(t,"America/Chicago");return t;}');
        for hour in range(1,169):p.evaluate('t=>__icarusSoak.realAdvance(t)',start+hour*3600000)
        s=self.snap(p);self.assertGreater(s['navigation']['arrivals'],0);self.assertEqual(s['knowledgeAudit'],[]);self.assertEqual(s['resourceAudit'],[]);self.assertEqual(s['frontierAudit'],[]);self.assertEqual(len(s['crew'])+len(s['living']['deceased']),20)
    def test_aborted_boarding_returns_paid_cargo_without_exhausting_an_unvisited_field_objective(self):
        p=self.page();self.field(p);self.change(p,"""s.tick=400;s.clock.elapsed=400;s.minute=880;const q=s.crew[0];q.expeditionAway=false;q.room='A04';q.nav=null;q.route=[];const m=s.remoteCore.missions.asteroid;m.phase='boarding';m.launched=0;s.remoteCore.director.registry.push({id:m.id,location:'asteroid',status:'active',crew:q.name,members:[q.name],type:'survey',baseline:{surveyed:1,findings:0}});s.remoteCore.director.intelligence.asteroid.attempts=2;s.remoteCore.director.intelligence.asteroid.pendingSurvey=true;""");self.advance(p,1);s=self.snap(p);intel=s['director']['intelligence']['asteroid'];self.assertEqual(intel['attempts'],2);self.assertEqual(intel['stagingFailures'],1);self.assertTrue(intel['pendingSurvey']);self.assertIsNone(s['missions']['asteroid']);self.assertEqual(s['resourceAudit'],[]);self.assertEqual(s['director']['registry'][-1]['completionReason'],'staging_access')
